using Godot;
using System;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Messaging;
public partial class NewGameFrontEnd
{
 bool DirectiveCancelStopCase=>FlowCase=="dircancel-stop";
 bool DirectiveCancelNoticeCase=>FlowCase=="dircancel-notice";
 TroopDispatch CancelDirectiveRoot()=>game!.Session.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Dispatches.First();
 TroopReceipt CancelDirectiveInitial()=>game!.Session.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Receipts.Single(r=>r.Id==CancelDirectiveRoot().Id);
 TroopDispatch ScopedCancellation()=>game!.Session.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Cancellation!.Dispatches.Single();
 UnitDirectiveCancelEffect ScopedCancelEffect()=>game!.Session.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Cancellation!.Effects.Single();
 UnitDirectiveCancelNotice ScopedCancelNotice()=>game!.Session.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Cancellation!.Notices.Single();
 UnitHeldTransfer CancelOriginalTransfer()=>game!.Session.DiagnosticSnapshot().NewMilitary!.HeldDelivery!.Transfers.First(t=>t.Action==NewMilitaryAction.DeliverHeldUnitDirective);
 async Task DirectiveCancellationStep(int n){await Frame();var s=game!.Session;
  if(n==0){game.SelectKnownMilitary(NewGameMilitary.UnitIdsFor(game!.Session.DiagnosticSnapshot())[1]);game.ChooseMilitary(NewMilitaryAction.RemoteRecall);game.Advance(s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Dispatches.Last().DueAt+5);if(DirectiveCancelStopCase){var k=NewGameMilitary.SelectKnownTarget(s.DiagnosticSnapshot(),NewGameMilitary.UnitIdsFor(game!.Session.DiagnosticSnapshot())[1])!;game.ExerciseUnitDirectiveGoal(new(k.Position.X+8000,k.Position.Y));}else game.Press("unit-directive-hold");Check(game.ButtonEnabled("unit-directive-cancel"),"own issued original has explicit cancellation action");}
  if(n==1){game.Advance(CancelDirectiveRoot().DueAt);Check(!CancelDirectiveInitial().Delivered,"original actually misses its declared old destination");}
  if(n==2){game.Advance(CancelDirectiveInitial().ReplyDueAt);game.Advance(Math.Max(s.Seconds,ArmyEnd()+2));Check(game.ButtonEnabled("unit-directive-handoff"),"actual original physically returned before use");}
  if(n==3){if(DirectiveCancelStopCase){game.Press("unit-directive-handoff");game.ExerciseDirectiveCancelAt(CancelOriginalTransfer().DueAt+2);Check(ScopedCancellation().DueAt==CancelOriginalTransfer().DueAt,"cancel and held original physically meet same fixed post");}else if(DirectiveCancelNoticeCase){game.ExerciseDirectiveCancelAt(s.Seconds+100);}else{game.Press("unit-directive-cancel");game.Press("unit-directive-retry");game.Press("unit-directive-handoff");Check(ScopedCancellation().DueAt==CancelOriginalTransfer().DueAt&&s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Dispatches.Last().DueAt==ScopedCancellation().DueAt,"original copy held paper and cancellation really arrive together");}Check(!s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Cancellation!.Effects.Any(),"dispatch alone cannot cancel original");Check(NewGameMilitary.UnitDirectiveCancellationStatus(s.DiagnosticSnapshot(),CancelDirectiveRoot().Id).Contains("返書未受領"),"actual distant effect never leaks into cancellation label");}
  if(n==4){game.Advance(ScopedCancellation().DueAt);var w=s.DiagnosticSnapshot();if(DirectiveCancelStopCase){Check(w.NewMilitary!.UnitDirective!.Holding!.Outcomes.Single().Outcome==UnitDirectiveOutcome.Applied&&w.NewMilitary.UnitDirective.Cancellation!.Effects.Length==0,"physical receipt waits for requested time while original starts");}else if(DirectiveCancelNoticeCase){game.Advance(w.NewMilitary!.UnitDirective!.Cancellation!.Receipts.Single().ReplyDueAt);Check(NewGameMilitary.UnitDirectiveCancellationStatus(s.DiagnosticSnapshot(),CancelDirectiveRoot().Id).Contains("効力時刻を待つ"),"initial physical reply describes waiting not unseen future effect");}else{Check(ScopedCancelEffect().Outcome==UnitCancelDisposition.Suppressed,"same-tick cancellation suppresses only root");Check(w.NewMilitary!.UnitDirective!.Effects.Single().Outcome==UnitDirectiveOutcome.Cancelled&&w.NewMilitary.UnitDirective.Holding!.Outcomes.Single().Outcome==UnitDirectiveOutcome.Cancelled,"both copy and held original are formally received without execution");}}
  if(n==5){if(DirectiveCancelStopCase){var w=s.DiagnosticSnapshot();long at=w.NewMilitary!.Requests.Single(q=>q.Input.Id==ScopedCancellation().Id).Input.DirectiveCancellation!.EffectiveAt;game.Advance(at);Check(ScopedCancelEffect().Outcome==UnitCancelDisposition.Stopped,"only physically received original movement is stopped at requested time");Check(s.DiagnosticSnapshot().NewMilitary!.Orders.Single(o=>o.Id==ScopedCancelEffect().StopOrder).AffectedUnits!.SequenceEqual(new[]{1}),"cancellation scope is left wing only");}else if(DirectiveCancelNoticeCase){var a=NewGameMilitary.Anchor(s.DiagnosticSnapshot());game.ExercisePersonalMove(new(a.X-40000,a.Y));var w=s.DiagnosticSnapshot();game.Advance(w.NewMilitary!.Requests.Single(q=>q.Input.Id==ScopedCancellation().Id).Input.DirectiveCancellation!.EffectiveAt);game.Advance(ScopedCancelNotice().DueAt);Check(!MessageFlow.Knows(s.DiagnosticSnapshot().Messaging,ScopedCancelNotice().Message,s.PlayerControl.Value)&&NewGameMilitary.HeldPapers(s.DiagnosticSnapshot(),s.Seconds).Any(h=>h.Message==ScopedCancelNotice().Message),"future effect result misses person and remains real held paper");Check(NewGameMilitary.UnitDirectiveCancellationStatus(s.DiagnosticSnapshot(),CancelDirectiveRoot().Id).Contains("効力時刻を待つ"),"unreceived result does not leak through UI");}else{game.Advance(s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Cancellation!.Receipts.Single().ReplyDueAt);Check(NewGameMilitary.UnitDirectiveCancellationStatus(s.DiagnosticSnapshot(),CancelDirectiveRoot().Id).Contains("未実行の対象原本を取消"),"person learns actual result only from delivered reply");}}
  if(n==6){if(DirectiveCancelNoticeCase){game.Advance(Math.Max(s.Seconds,PersonEnd()+1));game.ExercisePersonalMove(ScopedCancelNotice().Destination);game.Advance(PersonEnd()+1);Check(NewGameMilitary.HeldAllowed(s.DiagnosticSnapshot(),NewMilitaryAction.TakeHeldReply),"person actually returns to meet held result carrier");game.ChooseMilitary(NewMilitaryAction.TakeHeldReply);}else if(DirectiveCancelStopCase){game.Advance(ScopedCancelNotice().DueAt);Check(NewGameMilitary.UnitDirectiveCancellationStatus(s.DiagnosticSnapshot(),CancelDirectiveRoot().Id).Contains("対象原本による移動だけを停止"),"actual effect notice confirms scoped stop");}else{game.Advance(s.Seconds+3);Check(!s.DiagnosticSnapshot().NewMilitary!.Orders.Any(o=>o.Action==NewMilitaryAction.SendUnitDirective),"suppressed original never reappears later");}}
  if(n==7){if(DirectiveCancelNoticeCase){var t=s.DiagnosticSnapshot().NewMilitary!.HeldDelivery!.Transfers.Last();game.Advance(t.DueAt+1);Check(MessageFlow.Knows(s.DiagnosticSnapshot().Messaging,ScopedCancelNotice().Message,s.PlayerControl.Value)&&NewGameMilitary.UnitDirectiveCancellationStatus(s.DiagnosticSnapshot(),CancelDirectiveRoot().Id).Contains("未実行の対象原本を取消"),"physical paper recovery updates known cancellation result");}else{game.Advance(s.Seconds+3);game.Press("rotate");}Check(!CancelDirectiveInitial().Delivered,"initial failure journal is never overwritten by late delivery or cancellation");}
  game.Refresh();Check(game.RecognitionModelsMatch(),"actual cancellation 3D matches player recognition at"+n);game.Press("save");await WaitSave();
 }
 async Task BeginDirectiveCancellationContinuation(){for(int n=1;n<=7;n++)await MilitaryStep(n);for(int n=0;n<=4;n++)await RecognitionStep(n);for(int n=0;n<8;n++){await DirectiveCancellationStep(n);game!.SaveCheckpoint("dircancel"+n);await Capture("s"+n,true);}await Capture("final",true);}
 async Task RestoreDirectiveCancellation(){Press("load-list");await Frame();string id=File.ReadAllText(Path.Combine(TestOutput,"campaign-instance.txt"));savedList.Select(Array.FindIndex(savedRows,row=>row.Profile.Instance==id));Press("load");await Frame();for(int n=0;n<8;n++){game!.LoadCheckpoint("dircancel"+n);await Frame();await Frame();Check(game.Pose()==File.ReadAllText(Path.Combine(TestOutput,"s"+n+"-pose.json")),"same cancellation selected root knowledge actual units and 3D after restore"+n);await Capture("restored-s"+n,true);for(int k=n+1;k<8;k++)await DirectiveCancellationStep(k);Check(ContractJson.CanonicalHash(game.Session.DiagnosticSnapshot())==File.ReadAllText(Path.Combine(TestOutput,"final-world.sha256")),"same physical cancellation and scoped future after restore"+n);await Capture("continued-s"+n,true);GD.Print("UNIT_DIRECTIVE_CANCELLATION_RESTORED "+n);}}
 async Task RunDirectiveCancellationChecks(){if(OS.GetCmdlineUserArgs().Contains("--new-game-restore"))await RestoreDirectiveCancellation();else await BeginNewMilitaryFlow();if(OS.GetCmdlineUserArgs().Contains("--unit-directive-cancellation-film")){game!.LoadCheckpoint("dircancel4");game.Press("auto");string dir=Path.Combine(TestOutput,"film",TestKey??"normal");Directory.CreateDirectory(dir);for(int n=0;n<180;n++){await Frame();ViewportCapture.Save(GetViewport(),Path.Combine(dir,"cancel-"+n.ToString("D3")+".png"));}game.Press("pause");File.WriteAllText(Path.Combine(TestOutput,"film-manifest.json"),System.Text.Json.JsonSerializer.Serialize(new{Directory=Path.GetRelativePath(TestOutput,dir),Frames=180,Checkpoint=4,Action="moving-original-to-scoped-cancellation-effect"}));}File.WriteAllText(Path.Combine(TestOutput,OS.GetCmdlineUserArgs().Contains("--new-game-restore")?"restore-checks.json":"check-checks.json"),System.Text.Json.JsonSerializer.Serialize(assertions));GD.Print("UNIT_DIRECTIVE_CANCELLATION_PASSED "+FlowCase);}
}
